"use client";

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarRail,
} from "@/components/ui/sidebar";
import { SidebarNavigationMenu } from "@/components/ui/sidebar-utils";
import type { NavigationGroup } from "@/features/navigation/navigation.type";
import { SidebarUserButton } from "@/features/sidebar/sidebar-user-button";
import { useI18n } from "@/i18n/provider";
import { ChevronDown } from "lucide-react";
import { usePathname } from "next/navigation";
import type { PropsWithChildren } from "react";
import { useEffect, useState } from "react";
import { getAdminNavigation } from "./admin-navigation.links";

export function AdminSidebar() {
  const { t } = useI18n();
  const links: NavigationGroup[] = getAdminNavigation(t);

  return (
    <Sidebar variant="inset">
      <SidebarHeader className="flex flex-col gap-2">
        <div className="flex items-center gap-2 px-2 py-1.5">
          <div className="bg-primary text-primary-foreground flex size-8 items-center justify-center rounded-lg">
            <span className="text-sm font-semibold">A</span>
          </div>
          <span className="font-semibold">{t("admin.panel")}</span>
        </div>
      </SidebarHeader>
      <SidebarContent>
        {links.map((link) => (
          <ItemCollapsing
            defaultOpenStartPath={link.defaultOpenStartPath}
            key={link.title}
          >
            <SidebarGroup key={link.title}>
              <SidebarGroupLabel asChild>
                <CollapsibleTrigger>
                  {link.title}
                  <ChevronDown className="ml-auto transition-transform group-data-[state=open]/collapsible:rotate-180" />
                </CollapsibleTrigger>
              </SidebarGroupLabel>
              <CollapsibleContent>
                <SidebarGroupContent>
                  <SidebarNavigationMenu link={link} />
                </SidebarGroupContent>
              </CollapsibleContent>
            </SidebarGroup>
          </ItemCollapsing>
        ))}
      </SidebarContent>
      <SidebarFooter className="flex flex-col gap-2">
        <SidebarUserButton />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

const ItemCollapsing = (
  props: PropsWithChildren<{ defaultOpenStartPath?: string }>,
) => {
  const [open, setOpen] = useState(false);
  const pathname = usePathname();

  const isOpen = props.defaultOpenStartPath
    ? pathname.startsWith(props.defaultOpenStartPath)
    : true;

  useEffect(() => {
    if (isOpen) {
      setOpen(isOpen);
    }
  }, [isOpen]);
  return (
    <Collapsible
      defaultOpen={isOpen}
      onOpenChange={setOpen}
      open={open}
      className="group/collapsible"
    >
      {props.children}
    </Collapsible>
  );
};

content.thinking:
Je vois le problème maintenant ! Le composant `ItemCollapsing` utilise `useState(false)` comme état initial, et il y a un problème avec le `useEffect`.

Le code est:```tsx
const [open, setOpen] = useState(false);
const pathname = usePathname();

const isOpen = props.defaultOpenStartPath  ? pathname.startsWith(props.defaultOpenStartPath)
  : true;useEffect(() => {
  if (isOpen) {    setOpen(isOpen);  }}, [isOpen]);
```Le problème est que:1. `open` est initialisé à `false`2. Le `useEffect` s'exécute après le premier rendu
3. Pendant le premier rendu, les liens ne sont pas visibles car `open` est `false`

Même si `defaultOpen={isOpen}` est passé au `Collapsible`, le composant `Collapsible` utilise aussi `open={open}` qui est `false` initialement.

En fait, le vrai problème est que `open` est contrôlé par l'état local `open` qui est initialisé à `false`, et le `useEffect` ne s'exécute qu'après le premier rendu. Pendant le test E2E, le navigateur charge la page, et au premier rendu, les liens ne sont pas visibles.Regardons le fichier `admin-navigation.links.ts` pour voir si `defaultOpenStartPath` est défini.

